extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var enemy := find_by_name(main, "Enemy") as CharacterBody2D
	if not check("enemy", enemy != null, "Nella scena deve esserci il nemico"):
		return
	var code := source_of("res://enemy/enemy.gd")
	check("no_bools", not ("is_patrolling" in code or "is_attacking" in code), "Le variabili booleane is_patrolling e is_attacking devono essere rimosse da enemy.gd")

