extends CharacterBody2D

@export var speed: float = 100.0
@export var target: Node2D

var is_idle: bool = false
var is_patrolling: bool = true
var is_attacking: bool = false

var direction: float = 1.0

func _physics_process(_delta: float) -> void:
	if target and global_position.distance_to(target.global_position) < 50.0:
		is_attacking = true
		is_patrolling = false
		is_idle = false
	else:
		is_attacking = false
		is_patrolling = true
		is_idle = false

	if is_attacking:
		velocity.x = 0.0
	elif is_patrolling:
		velocity.x = direction * speed
		if is_on_wall():
			direction *= -1.0
	else:
		velocity.x = 0.0
	move_and_slide()

class_name State
extends Node

signal transitioned(state: State, new_state_name: String)

func enter() -> void:
	pass

func exit() -> void:
	pass

func update(_delta: float) -> void:
	pass

func physics_update(_delta: float) -> void:
	pass

class_name StateMachine
extends Node

@export var initial_state: State

var current_state: State
var states: Dictionary = {}

func _ready() -> void:
	await owner.ready
	for child in get_children():
		if child is State:
			states[child.name.to_lower()] = child
			child.transitioned.connect(_on_child_transitioned)
	if initial_state:
		initial_state.enter()
		current_state = initial_state

func _physics_process(delta: float) -> void:
	if current_state:
		current_state.physics_update(delta)

func _on_child_transitioned(state: State, new_state_name: String) -> void:
	if state != current_state:
		return
	var new_state: State = states.get(new_state_name.to_lower())
	if not new_state:
		return
	if current_state:
		current_state.exit()
	new_state.enter()
	current_state = new_state

class_name EnemyIdleState
extends State

@export var enemy: CharacterBody2D

func physics_update(_delta: float) -> void:
	enemy.velocity.x = 0.0
	enemy.move_and_slide()
	if enemy.target and enemy.global_position.distance_to(enemy.target.global_position) < 50.0:
		transitioned.emit(self, "attack")
	else:
		transitioned.emit(self, "patrol")

class_name EnemyPatrolState
extends State

@export var enemy: CharacterBody2D

func physics_update(_delta: float) -> void:
	enemy.velocity.x = enemy.direction * enemy.speed
	if enemy.is_on_wall():
		enemy.direction *= -1.0
	enemy.move_and_slide()
	if enemy.target and enemy.global_position.distance_to(enemy.target.global_position) < 50.0:
		transitioned.emit(self, "attack")

class_name EnemyAttackState
extends State

@export var enemy: CharacterBody2D

func physics_update(_delta: float) -> void:
	enemy.velocity.x = 0.0
	enemy.move_and_slide()
	if not enemy.target or enemy.global_position.distance_to(enemy.target.global_position) >= 50.0:
		transitioned.emit(self, "patrol")

